import { LucideIcon } from "lucide-react";
import React from "react";

export interface NavItem {
  id: string;
  label: string;
  icon: LucideIcon;
  component: React.ReactNode;
  category?: string;
  priority?: number;
}

export interface NavGroup {
  title: string;
  items: string[]; // Array of NavItem IDs
  icon: LucideIcon;
}

class NavigationRegistry {
  private items: Map<string, NavItem> = new Map();
  private groups: NavGroup[] = [];

  registerItem(item: NavItem) {
    this.items.set(item.id, item);
  }

  registerGroup(group: NavGroup) {
    this.groups.push(group);
  }

  getItem(id: string): NavItem | undefined {
    return this.items.get(id);
  }

  getAllItems(): NavItem[] {
    return Array.from(this.items.values());
  }

  getGroups(): NavGroup[] {
    return this.groups;
  }

  // Helper to get flattened items for search/command menu
  getFlattenedItems() {
    return Array.from(this.items.values()).map(item => ({
      id: item.id,
      label: item.label,
      icon: item.icon
    }));
  }
}

export const navigationRegistry = new NavigationRegistry();

