                  <div className="bg-primary text-white text-[10px] font-bold px-2 py-1 rounded shadow-lg uppercase tracking-widest">
                    Drag to move {widget.label}
                  </div>
                </div>
              )}
              <div className="h-full w-full overflow-hidden">
