import React from "react";
import {
  LayoutDashboard,
  Box,
  MessageSquare,
  Workflow,
  Sparkles,
  FolderOpen,
  Settings,
  Activity,
  Brain,
  FileText,
  Rocket,
  History,
  Network,
  Cpu,
  FlaskConical,
  Code2,
  Cloud,
  Layers,
  Zap,
  Shield,
  Gauge,
} from "lucide-react";
import { navigationRegistry } from "./navigationRegistry";

// Component Imports using central aliases
import { NeuralLinkChat } from "@/components/dashboard/NeuralLinkChat";
import { SettingsPanel } from "@/components/dashboard/SettingsPanel";
import { FileExplorer } from "@/components/dashboard/FileExplorer";
import { RobotkezV2Chat } from "@/components/dashboard/RobotkezV2Chat";
import { AgentManagementPanel } from "@/components/dashboard/AgentManagementPanel";
import { TaskQueueMonitor } from "@/components/dashboard/TaskQueueMonitor";
import { KnowledgeBasePanel } from "@/components/dashboard/KnowledgeBasePanel";
import { IncubatorPanel } from "@/components/dashboard/IncubatorPanel";
import { DeveloperPanel } from "@/components/dashboard/DeveloperPanel";
import { EdgePanel } from "@/components/dashboard/EdgePanel";
import { JulesPanel } from "@/components/dashboard/JulesPanel";
import { TrackGenerator } from "@/components/dashboard/TrackGenerator";
import { TaskDecomposerPanel } from "@/components/dashboard/TaskDecomposerPanel";
import { SuggestedTasksWidget } from "@/components/dashboard/SuggestedTasksWidget";
import { CEANLayout } from "@/components/cean/CEANLayout";
import { CloudflareDeployment } from "@/pages/CloudflareDeployment";
import FleetManager from "@/pages/FleetManager";
import { NeuralMap } from "@/pages/NeuralMap";
import { MCPCommandCenter } from "@/components/dashboard/MCPCommandCenter";
import { InventoryCatalog } from "@/components/dashboard/InventoryCatalog";
import { TestResultsWidget } from "@/components/dashboard/TestResultsWidget";
import { EmbeddedWorkflow } from "@/components/dashboard/EmbeddedWorkflow";

export function initializeNavigation() {
  // 1. Register Items
  navigationRegistry.registerItem({
    id: "dashboard",
    label: "Mission Control",
    icon: LayoutDashboard,
    component: null, // Handled specially in Layout
  });

  navigationRegistry.registerItem({
    id: "neural-map",
    label: "Neural Map",
    icon: Network,
    component: <NeuralMap />,
  });

  navigationRegistry.registerItem({
    id: "cean",
    label: "CEAN Orchestrator",
    icon: Rocket,
    component: <CEANLayout />,
  });

  navigationRegistry.registerItem({
    id: "cloudflare",
    label: "Cloudflare Deploy",
    icon: Cloud,
    component: <CloudflareDeployment />,
  });

  navigationRegistry.registerItem({
    id: "fleet_manager",
    label: "Fleet Manager",
    icon: Cpu,
    component: <FleetManager />,
  });

  navigationRegistry.registerItem({
    id: "chat",
    label: "Neural Chat",
    icon: MessageSquare,
    component: <NeuralLinkChat />,
  });

  navigationRegistry.registerItem({
    id: "management",
    label: "Agent Roster",
    icon: Sparkles,
    component: <AgentManagementPanel />,
  });

  navigationRegistry.registerItem({
    id: "decomposer",
    label: "Decompose",
    icon: Layers,
    component: <TaskDecomposerPanel />,
  });

  navigationRegistry.registerItem({
    id: "tracks",
    label: "Tracks",
    icon: History,
    component: <TrackGenerator />,
  });

  navigationRegistry.registerItem({
    id: "incubator",
    label: "Incubator",
    icon: FlaskConical,
    component: <IncubatorPanel />,
  });

  navigationRegistry.registerItem({
    id: "knowledge",
    label: "Neural Knowledge",
    icon: Brain,
    component: <KnowledgeBasePanel />,
  });

  navigationRegistry.registerItem({
    id: "mcp",
    label: "MCP Command Center",
    icon: Shield,
    component: <MCPCommandCenter />,
  });

  navigationRegistry.registerItem({
    id: "developer",
    label: "Developer",
    icon: Code2,
    component: <DeveloperPanel />,
  });

  navigationRegistry.registerItem({
    id: "edge",
    label: "Edge",
    icon: Zap,
    component: <EdgePanel />,
  });

  navigationRegistry.registerItem({
    id: "suggested-tasks",
    label: "Suggested",
    icon: FileText,
    component: <SuggestedTasksWidget />,
  });

  navigationRegistry.registerItem({
    id: "tests",
    label: "Precision Tests",
    icon: Gauge,
    component: <TestResultsWidget />,
  });

  navigationRegistry.registerItem({
    id: "robotkez",
    label: "Robotkéz",
    icon: Activity,
    component: <RobotkezV2Chat />,
  });

  navigationRegistry.registerItem({
    id: "tasks",
    label: "Task Queue",
    icon: History,
    component: <TaskQueueMonitor />,
  });

  navigationRegistry.registerItem({
    id: "inventory",
    label: "Assets",
    icon: Box,
    component: <InventoryCatalog />,
  });

  navigationRegistry.registerItem({
    id: "files",
    label: "Filesystem",
    icon: FolderOpen,
    component: <FileExplorer />,
  });

  navigationRegistry.registerItem({
    id: "settings",
    label: "System Config",
    icon: Settings,
    component: <SettingsPanel />,
  });

  navigationRegistry.registerItem({
    id: "n8n",
    label: "n8n Automation",
    icon: Workflow,
    component: (
      <EmbeddedWorkflow
        title="n8n Automation"
        url={"http://localhost:5678"}
        icon={<Workflow size={20} className="text-[#FF6D5A]" />}
      />
    ),
  });

  navigationRegistry.registerItem({
    id: "langflow",
    label: "Langflow Orchestration",
    icon: Sparkles,
    component: (
      <EmbeddedWorkflow
        title="Langflow Orchestration"
        url={"http://localhost:3000"}
        icon={<Sparkles size={20} className="text-violet-500" />}
      />
    ),
  });

  // 2. Register Groups
  navigationRegistry.registerGroup({
    title: "Core Systems",
    icon: Layers,
    items: ["dashboard", "neural-map"],
  });

  navigationRegistry.registerGroup({
    title: "AI & Agents",
    icon: Brain,
    items: ["chat", "management", "decomposer", "incubator", "knowledge", "developer", "edge", "robotkez"],
  });

  navigationRegistry.registerGroup({
    title: "Orchestration",
    icon: Rocket,
    items: ["cean", "cloudflare", "fleet_manager", "tasks"],
  });

  navigationRegistry.registerGroup({
    title: "Project Mgmt",
    icon: FileText,
    items: ["tracks", "suggested-tasks", "tests"],
  });

  navigationRegistry.registerGroup({
    title: "System",
    icon: Settings,
    items: ["inventory", "files", "settings", "n8n", "langflow"],
  });
}

